/* @lc app=leetcode id=1643 lang=kotlin */ class Solution { fun kthSmallestPath(destination: IntArray, k: Int): String = intArrayOf(destination[0], destination[1], k).let { st -> CharArray(destination[0] + destination[1]) { ((1..st[0]).fold(1L) { a, i -> a * (st[0] + st[1] - i) / i }).let { c -> if (st[1] > 0 && st[2] <= c) 'H'.also { st[1]-- } else 'V'.also { if (st[1] > 0) st[2] -= c.toInt() }.also { st[0]-- } } }.concatToString() } }